document.querySelector("#batch39 .grid").insertAdjacentHTML("beforeend","<a class=\"card\" href=\"summaries/mahmoud-15455360.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف المسيخ الدجال\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>المسيخ الدجال</h3><p>تعرف صفحة الطبعة المسيخ الدجال بوصفه مجموعة قصصية تستخدم الفانتازيا والرمز لطرح أسئلة فكرية وسياسية. لذلك لا ينبغي اختيار الكتاب على أساس أنه درا…</p><small>مصطفى محمود</small></a><a class=\"card\" href=\"summaries/mahmoud-15455364.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف أكل عيش- المجموعة القصصية الأولى لمصطفى محمود\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>أكل عيش- المجموعة القصصية الأولى لمصطفى محمود</h3><p>تصف النبذة مجموعة قصصية يطلب أشخاصها لحظة تمنح العيش معنى يتجاوز تدبير القوت. يجمعهم الضيق بالاستمرار وحده، مع اختلاف البيئات والوجوه. يظهر السؤا…</p><small>مصطفى محمود</small></a><a class=\"card\" href=\"summaries/mahmoud-15455335.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف الأفيون\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>الأفيون</h3><p>تعرّف نبذة الطبعة الأفيون كرواية اجتماعية تتقاطع فيها التقاليد العائلية وأسئلة الدين والاختيار. وتضع محمد أفندي داخل شدّ بين طموحه وما ينتظره منه…</p><small>مصطفى محمود</small></a>");
